head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.vBzProcsNo = "";
scwin.vListBzTpCd = "";
scwin.clickListBzDtlTpCd = "";
scwin.clickAdjReqProcsNo = "";
scwin.pMenuID = $c.cm.InfoMenuID();
//var fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.fn_GetPar, scwin.fn_SetPar;
// dialog 호출용 함수
// 발행기관목록관련
scwin.vScrenID = "ULDSTF40005.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    var url = "/StockOptionDutyHold.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listAdjReq";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    url += "&LIST_INVSTG_BZ_TP_CD=" + scwin.vListBzTpCd;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_setBzProcsNo = function(obj) {
    scwin.clickListBzDtlTpCd = dts_List.getCellData(eval(obj), "LIST_BZ_DTL_TP_CD");
    scwin.clickAdjReqProcsNo = dts_List.getCellData(eval(obj), "ADJ_REQ_PROCS_NO");
    //alert(clickListBzDtlTpCd);

};




//접수 또는 반려처리
scwin.fn_trs = function(listProcsStatCd) {
    vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    trs_Save.Action = $c.lc.fn_encodeNSession("/StockOptionDutyHold.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=processAdjReq");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Save.Parameters = "TRS_IDX=U" + ",LIST_PROCS_STAT_CD=" + listProcsStatCd + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",LIST_BZ_TP_CD=" + scwin.vListBzTpCd + ",LIST_BZ_DTL_TP_CD=" + scwin.clickListBzDtlTpCd + ",PROCS_EMP_NO=" + js_emp_no + ",ADJ_REQ_PROCS_NO=" + scwin.clickAdjReqProcsNo;
    trs_Save.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.grd_List_OnDblClick = function(row, colid) {
    scwin.fn_setBzProcsNo(row);
    //alert ( clickAdjReqProcsStatCd );
    if ("FUNC_ACPT" == colid) {
        var vAnswer = confirm('승인처리 하시겠습니까?');
        if (vAnswer == true) {
            LastJob = "승인";
            scwin.fn_trs("35");
        }
    } else if ("FUNC_RJCT" == colid) {
        var vAnswer = confirm('불가처리 하시겠습니까?');
        if (vAnswer == true) {
            LastJob = "불가";
            scwin.fn_trs("36");
        }
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_list_sync();
    scwin.fn_parentRefresh();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    var parentWin = $c.frame.path("../");
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.vListBzTpCd = "200";
    scwin.fn_list_sync();
};
